// Root-side Explorer QA teardown. It runs as
// `sudo -n /usr/bin/node --input-type=module - <operation> … --owner U`
// with this source on stdin, so it imports only Node built-ins, stays
// compatible with Node 20 and never depends on its own file location. The CLI
// accepts only the pinned QA paths and refuses unless it runs as uid 0.
//
// Operations:
//   plan-workspace --scope S --mode M --owner U [--measure]  read-only keep-set proof
//   reduce-workspace --scope S --plan-digest D --owner U     keep-data reduction
//   stash-policy --owner U                                    park the router access policy in the state dir
//   stash-restore --owner U                                   copy the stash into the fresh policy, then remove it
//   stash-clear --owner U                                     remove the stash
//   delete-data --owner U                                     rename the workspace and the state dir to
//                                                             tombstones, then remove both
//   finish-deletions --owner U                                remove leftover delete-data tombstones
//   plan-legacy-backups --owner U                             read-only preview of the legacy-backup prune
//   remove-legacy-backups --owner U                           prune classified legacy backups
//
// Every deletion is `fs.rmSync` on a path proven to be on the same device,
// owned as expected, never a followed link and with no mount at or under it;
// the mount table is read again immediately before each removal.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

export const QA_TEARDOWN_PATHS = Object.freeze({
    workspace: '/home/admin/explorerQaWorkspace',
    state: '/home/admin/.qa-deployment-state',
    backups: '/home/admin/.qa-deployment-backups',
});
export const SCOPES = Object.freeze(['rebuild', 'fresh', 'destroy']);
export const MODES = Object.freeze(['keep-data', 'delete-data']);

// Keep these lists literal; the admin module has its own copy and a test compares them.
// The encryption identity as rollback-explorer-qa.mjs `AUTH_FILES` fingerprints it.
export const AUTH_FILES = Object.freeze(['.env', '.ploinky/data/master-key', '.ploinky/master-key',
    '.ploinky/data/.secrets', '.ploinky/.secrets', '.ploinky/data/passwords.enc', '.ploinky/passwords.enc',
    '.ploinky/data/ploinky_subject_identity_ed25519_v1.enc', '.ploinky/ploinky_subject_identity_ed25519_v1.enc']);
// The pinned Ploinky runtime refuses these retired controller secrets; a deploy refuses them before `mark`.
export const RETIRED_IDENTITY = Object.freeze(['.ploinky/master-key', '.ploinky/.secrets',
    '.ploinky/ploinky_subject_identity_ed25519_v1.enc']);
// The preservation rule of the deploy workflow (`// BEGIN QA durable workspace preservation`):
// top-level entries regenerated by a deploy, the second-level runtime entries of `.ploinky`
// and the graph data under `.ploinky/data`. Everything else is kept (decision D1).
export const REGENERATED_TOP = Object.freeze(['.ploinky', '.runtime', 'AdvancedLanguageAgent']);
export const RUNTIME_ENTRIES = Object.freeze(['agents.json', 'routing.json', 'running', 'run', 'logs', 'box',
    'deps', 'repos', 'agentlib', 'container-runtime', 'graph-skill-scope.json', 'data',
    'enabled_repos.json', 'repo_sources.json', 'unregistered_agent_repos.json']);
export const GENERATED_DATA = Object.freeze(['edge-routing', 'edge-publication', 'router-security']);
// The deploy workflow's own staging files; the credentials file holds plaintext tokens.
export const STAGING_FILES = Object.freeze(['.explorer-qa-edge-desired.json', '.explorer-qa-cloudflare-credentials.json']);
// Ploinky creates per-agent symlinks here; real files and directories are operator content.
export const LINK_DIRECTORIES = Object.freeze(['.ploinky/code', '.ploinky/skills']);
// The router access policy the deploy restores (the list of the policy restoration block).
export const POLICY_ENTRIES = Object.freeze(['policy-state.json', 'sessions-revocations.json', 'policy-audit.log',
    'policy-audit-archive']);
export const STASH_NAME = 'router-security';
export const MARKER_NAME = 'install-pending.json';

// Legacy backups, ported from the retired privileged backup helper at 916078b2 (I1). Keep these lists literal.
export const BACKUP_INNER_ENTRIES = Object.freeze({
    completion: Object.freeze(['helpers', 'prior-containers.txt', 'rollback-authority.json', 'preservation.json',
        'workspace', 'quiesce.log', 'quiesce-source.mjs', 'lock-ready.json', 'lock-released.json', 'lock-release',
        'lock.log', 'lock-source.txt', 'policy-restoration.json', 'restored-selections.json']),
    rollbackMarkers: Object.freeze(['rollback-result.json', /^rollback-result\.json\.[a-f0-9]{16}$/, 'failed-workspace']),
});
export const BACKUP_SIBLING_SUFFIXES = Object.freeze(['helpers', 'lock-ready.json', 'lock-released.json', 'lock-release',
    'lock.log', 'lock-source.txt', 'quiesce.log']);
export const RETAINED_CLASSES = Object.freeze(['rollback-attempted', 'unrecognized-entry', 'stop-attempted-unpreserved',
    'incomplete-redeploy']);
export const PRUNABLE_CLASSES = Object.freeze(['complete-redeploy', 'no-workspace']);

const BACKUP = /^redeploy-[A-Za-z0-9]{8}$/;
const TOMBSTONE = /^\.pruning-(redeploy-[A-Za-z0-9]{8})$/;
const SIBLING = /^(redeploy-[A-Za-z0-9]{8})-(helpers|lock-ready\.json|lock-released\.json|lock-release|lock\.log|lock-source\.txt|quiesce\.log)$/;
const FULL_ID = /^[a-f0-9]{64}$/;
const DIRECTORY_ENTRIES = new Set(['helpers', 'workspace']);
const RECEIPT_LIMIT = 1024 * 1024;
const IDENTITY_LIMIT = 64 * 1024 * 1024;
const LEFTOVER = /^router-security\.(?:tmp|removing)-[0-9]+$/;
const DIGEST = /^sha256:[a-f0-9]{64}$/;

function requireProof(condition, code, extra = {}) {
    if (!condition) throw Object.assign(new Error(code), { code, ...extra });
}

const sha256 = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const typeOf = stat => stat.isSymbolicLink() ? 'symlink' : stat.isDirectory() ? 'directory' : stat.isFile() ? 'file' : 'other';
const realDirectory = stat => Boolean(stat && stat.isDirectory() && !stat.isSymbolicLink());

/** Mount points of `/proc/self/mountinfo` (field 5, with its octal escapes decoded). Copied from the retired privileged backup helper at 916078b2. */
export function parseMountPoints(text) {
    return text.split('\n').filter(Boolean).map(line => String(line.split(' ')[4] || '')
        .replace(/\\([0-7]{3})/g, (_, octal) => String.fromCharCode(parseInt(octal, 8))));
}

function readMountPoints() {
    // QA runs on Linux; other platforms have no mount table here and run only the tests.
    if (process.platform !== 'linux') return [];
    let text = '';
    try { text = fs.readFileSync('/proc/self/mountinfo', 'utf8'); } catch {}
    const points = parseMountPoints(text);
    requireProof(points.length > 0 && points.every(point => path.isAbsolute(point)), 'QA_TEARDOWN_MOUNTS_UNREADABLE');
    return points;
}

/**
 * Shared filesystem context. `hooks` exist for in-process tests only:
 * `lstat(file, stat)` may substitute device or inode identities,
 * `mountPoints()` replaces the mount table, `afterRemove(relative)`,
 * `afterCopy(name)` and `afterRename(file)` run after each step so a test can
 * inject a crash, and `beforeRead(file)` runs before a receipt is read.
 */
function context({ paths, owner, hooks = {} }) {
    requireProof(paths && [paths.workspace, paths.state, paths.backups].every(item => typeof item === 'string'
        && path.isAbsolute(item) && path.normalize(item) === item && item !== '/')
        && new Set([paths.workspace, paths.state, paths.backups]).size === 3
        && [paths.workspace, paths.state, paths.backups].every(left => [paths.workspace, paths.state, paths.backups]
            .every(right => left === right || !right.startsWith(left + path.sep)))
        && Number.isSafeInteger(owner) && owner > 0, 'QA_TEARDOWN_USAGE_INVALID');
    const lstat = file => {
        const stat = fs.lstatSync(file, { bigint: true });
        return hooks.lstat ? hooks.lstat(file, stat) : stat;
    };
    const present = file => {
        try { return lstat(file); } catch (error) { if (error.code === 'ENOENT') return null; throw error; }
    };
    const mountPoints = () => hooks.mountPoints ? hooks.mountPoints() : readMountPoints();
    // Contract 1 r2: a mount at or under `top` refuses. A bind mount from the same
    // filesystem keeps its device, so the device walk alone cannot see it.
    const assertNoMount = top => requireProof(!mountPoints().some(point => point === top || point.startsWith(top + path.sep)),
        'QA_TEARDOWN_MOUNT_INSIDE');
    return { paths, owner: BigInt(owner), hooks, lstat, present, assertNoMount };
}

/**
 * Walks `top` with lstat only; links are never followed. Every entry must be
 * on `dev`, otherwise the walk refuses with `QA_TEARDOWN_MOUNT_INSIDE`.
 * Returns the allocated bytes, counting each hard-linked inode once.
 */
function walkSameDevice(ctx, top, dev, seen = new Set()) {
    let bytes = 0n;
    const account = stat => {
        const key = `${stat.dev}:${stat.ino}`;
        if (seen.has(key)) return;
        seen.add(key);
        bytes += stat.blocks * 512n;
    };
    const root = ctx.lstat(top);
    requireProof(root.dev === dev, 'QA_TEARDOWN_MOUNT_INSIDE');
    account(root);
    if (!realDirectory(root)) return bytes;
    const stack = [top];
    while (stack.length) {
        const directory = stack.pop();
        for (const name of readdirPresent(directory)) {
            const file = path.join(directory, name);
            // A running Box may remove an entry between readdir and lstat; a vanished entry is on no other device.
            const stat = ctx.present(file);
            if (!stat) continue;
            requireProof(stat.dev === dev, 'QA_TEARDOWN_MOUNT_INSIDE');
            account(stat);
            if (realDirectory(stat)) stack.push(file);
        }
    }
    return bytes;
}

function readdirPresent(directory) {
    try { return fs.readdirSync(directory); } catch (error) { if (error.code === 'ENOENT') return []; throw error; }
}

const escapeRegExp = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// A delete-data tombstone sits beside its directory: `/home/admin/.explorerQaWorkspace.deleting-<pid>`
// and `/home/admin/.qa-deployment-state.deleting-<pid>`.
const deletingPrefix = file => `${path.basename(file).startsWith('.') ? '' : '.'}${path.basename(file)}.deleting-`;

/**
 * Leftover delete-data tombstones of exactly the workspace and the state
 * directory, each proven a real directory owned by the admin on its parent's
 * device, with no mount at or under it. Deploy routes never look at them.
 */
function pendingDeletions(ctx) {
    const pending = [];
    for (const file of [ctx.paths.workspace, ctx.paths.state]) {
        const parent = path.dirname(file);
        const pattern = new RegExp(`^${escapeRegExp(deletingPrefix(file))}[0-9]+$`);
        const names = readdirPresent(parent).filter(name => pattern.test(name)).sort();
        if (names.length === 0) continue;
        const parentStat = ctx.lstat(parent);
        for (const name of names) {
            const tombstone = path.join(parent, name);
            const stat = ctx.lstat(tombstone);
            requireProof(realDirectory(stat) && stat.uid === ctx.owner && stat.dev === parentStat.dev
                && fs.realpathSync(tombstone) === tombstone, 'QA_TEARDOWN_TOMBSTONE_INVALID');
            ctx.assertNoMount(tombstone);
            walkSameDevice(ctx, tombstone, stat.dev);
            pending.push({ name, file: tombstone, stat });
        }
    }
    return pending;
}

/** The recursive `{path, type, ino, size}` listing of `top`, skipping the `skip` relatives. Directory sizes are null. */
function listTree(ctx, top, skip = new Set()) {
    const rows = [];
    const visit = (relative, stat) => rows.push({ path: relative, type: typeOf(stat), ino: String(stat.ino),
        size: realDirectory(stat) ? null : String(stat.size) });
    visit('.', ctx.lstat(top));
    const stack = [''];
    while (stack.length) {
        const relativeDirectory = stack.pop();
        const names = readdirPresent(relativeDirectory ? path.join(top, relativeDirectory) : top).sort();
        for (const name of names) {
            const relative = relativeDirectory ? `${relativeDirectory}/${name}` : name;
            if (skip.has(relative)) continue;
            // Every walk skips an entry that vanished after readdir. Only the pre-mark plan runs beside a live
            // Box; the reduction and every removal run after the stop, where nothing is expected to vanish.
            const stat = ctx.present(path.join(top, relative));
            if (!stat) continue;
            visit(relative, stat);
            if (realDirectory(stat)) stack.push(relative);
        }
    }
    return rows.sort((left, right) => left.path < right.path ? -1 : left.path > right.path ? 1 : 0);
}

/** The state directory: absent, or a private real directory owned by the admin. */
function stateDirectory(ctx) {
    const { state } = ctx.paths;
    const stat = ctx.present(state);
    if (!stat) return null;
    requireProof(realDirectory(stat) && stat.uid === ctx.owner && (stat.mode & 0o077n) === 0n
        && fs.realpathSync(state) === state, 'QA_TEARDOWN_STATE_INVALID');
    const stash = ctx.present(path.join(state, STASH_NAME));
    requireProof(!stash || realDirectory(stash), 'QA_TEARDOWN_STATE_INVALID');
    return { stat, stash: Boolean(stash) };
}

function livePolicy(ctx) {
    const directory = path.join(ctx.paths.workspace, '.ploinky/data/router-security');
    const stat = ctx.present(directory);
    if (!stat) return null;
    requireProof(realDirectory(stat), 'QA_TEARDOWN_UNSAFE_PATH');
    const policy = ctx.present(path.join(directory, 'policy-state.json'));
    return { directory, initialized: Boolean(policy && policy.isFile() && !policy.isSymbolicLink()) };
}

function identityFingerprint(ctx) {
    const { workspace } = ctx.paths;
    return AUTH_FILES.flatMap(relative => {
        const file = path.join(workspace, relative);
        const stat = ctx.present(file);
        if (!stat) return [];
        requireProof(stat.isFile() && !stat.isSymbolicLink() && stat.nlink === 1n && stat.size <= BigInt(IDENTITY_LIMIT),
            'QA_TEARDOWN_UNSAFE_PATH');
        return [{ relative, sha256: sha256(fs.readFileSync(file)), uid: Number(stat.uid), gid: Number(stat.gid),
            mode: Number(stat.mode & 0o7777n), nlink: Number(stat.nlink) }];
    });
}

/** The deletion targets of keep-data mode, relative to the workspace (contract 1 r2). */
function deletionTargets(ctx) {
    const { workspace } = ctx.paths;
    const targets = [];
    const add = relative => {
        const stat = ctx.present(path.join(workspace, relative));
        if (stat) targets.push({ relative, stat });
    };
    for (const name of REGENERATED_TOP.filter(item => item !== '.ploinky')) add(name);
    const state = path.join(workspace, '.ploinky');
    if (ctx.present(state)) {
        for (const name of fs.readdirSync(state).sort()) {
            if ((RUNTIME_ENTRIES.includes(name) && name !== 'data') || STAGING_FILES.includes(name)) add(`.ploinky/${name}`);
        }
        for (const directory of LINK_DIRECTORIES) {
            if (!ctx.present(path.join(workspace, directory))) continue;
            for (const name of fs.readdirSync(path.join(workspace, directory)).sort()) {
                if (ctx.lstat(path.join(workspace, directory, name)).isSymbolicLink()) add(`${directory}/${name}`);
            }
        }
        if (ctx.present(path.join(state, 'data'))) for (const name of GENERATED_DATA) add(`.ploinky/data/${name}`);
    }
    return targets.sort((left, right) => left.relative < right.relative ? -1 : left.relative > right.relative ? 1 : 0);
}

function planDigest(value) {
    return `sha256:${sha256(JSON.stringify(value))}`;
}

/**
 * Read-only workspace plan (contract 1 r2). Keep-data mode refuses with
 * `QA_TEARDOWN_UNSAFE_PATH`, `QA_TEARDOWN_RETIRED_IDENTITY` (deploy scopes),
 * `QA_TEARDOWN_KEY_MISSING` or `QA_TEARDOWN_MOUNT_INSIDE`, and records the
 * recursive keep listing and the identity fingerprint. Delete-data mode proves
 * the workspace and the state directory can be removed without leaving them.
 * `measure` adds the allocated bytes of the deletion targets.
 */
export function planWorkspace({ paths, owner, scope, mode, measure = false, hooks = {} }) {
    requireProof(SCOPES.includes(scope) && MODES.includes(mode) && (mode === 'keep-data' || scope === 'destroy'),
        'QA_TEARDOWN_USAGE_INVALID');
    const ctx = context({ paths, owner, hooks });
    const { workspace } = ctx.paths;
    const state = stateDirectory(ctx);
    const top = ctx.present(workspace);
    // Only a destroy finishes leftover delete-data tombstones, so only its plan proves them.
    const base = { result: 'planned', scope, mode,
        pendingDeletions: scope === 'destroy' ? pendingDeletions(ctx).map(item => item.name) : [] };
    if (!top) {
        const value = { ...base, workspace: 'absent', keep: { count: 0, top: [], digest: planDigest([]) }, identity: [],
            delete: [], stash: state?.stash ? 'keep' : 'none', state: state ? 'present' : 'absent',
            reclaimableBytes: measure ? 0 : null };
        if (mode === 'delete-data' && state) {
            ctx.assertNoMount(ctx.paths.state);
            const bytes = walkSameDevice(ctx, ctx.paths.state, state.stat.dev);
            value.reclaimableBytes = measure ? Number(bytes) : null;
        }
        value.digest = planDigest({ version: 1, workspace, scope, mode, keep: [], identity: [], delete: [], stash: value.stash,
            state: value.state });
        return Object.defineProperty(value, 'keepListing', { value: [], enumerable: false });
    }
    requireProof(realDirectory(top) && top.uid === ctx.owner && fs.realpathSync(workspace) === workspace, 'QA_TEARDOWN_UNSAFE_PATH');

    if (mode === 'delete-data') {
        ctx.assertNoMount(workspace);
        let bytes = walkSameDevice(ctx, workspace, top.dev);
        if (state) {
            ctx.assertNoMount(ctx.paths.state);
            bytes += walkSameDevice(ctx, ctx.paths.state, state.stat.dev);
        }
        const value = { ...base, workspace: 'present', keep: { count: 0, top: [], digest: planDigest([]) }, identity: [],
            delete: [{ relative: '.', type: 'directory' }], stash: state?.stash ? 'keep' : 'none',
            state: state ? 'present' : 'absent', reclaimableBytes: measure ? Number(bytes) : null };
        value.digest = planDigest({ version: 1, workspace, scope, mode, ino: String(top.ino), delete: value.delete,
            stash: value.stash, state: value.state });
        return Object.defineProperty(value, 'keepListing', { value: [], enumerable: false });
    }

    for (const relative of ['.ploinky', '.ploinky/data', ...LINK_DIRECTORIES, '.data', '.runtime']) {
        const stat = ctx.present(path.join(workspace, relative));
        requireProof(!stat || realDirectory(stat), 'QA_TEARDOWN_UNSAFE_PATH');
    }
    const identity = identityFingerprint(ctx);
    const policy = livePolicy(ctx);
    if (scope !== 'destroy') {
        const retired = RETIRED_IDENTITY.filter(relative => ctx.present(path.join(workspace, relative)));
        requireProof(retired.length === 0, 'QA_TEARDOWN_RETIRED_IDENTITY', { detail: { retired } });
    }
    requireProof(!ctx.present(path.join(workspace, '.data')) || ctx.present(path.join(workspace, '.ploinky/data/master-key')),
        'QA_TEARDOWN_KEY_MISSING');
    ctx.assertNoMount(workspace);

    const targets = deletionTargets(ctx);
    const seen = new Set();
    let bytes = 0n;
    for (const target of targets) bytes += walkSameDevice(ctx, path.join(workspace, target.relative), top.dev, seen);
    const keepListing = listTree(ctx, workspace, new Set(targets.map(target => target.relative)));
    const keepDigest = planDigest(keepListing);
    const stash = state?.stash ? 'keep' : policy?.initialized ? 'create' : 'none';
    const deletions = targets.map(target => ({ relative: target.relative, type: typeOf(target.stat) }));
    const value = { ...base, workspace: 'present',
        keep: { count: keepListing.length, top: keepListing.filter(row => row.path !== '.' && !row.path.includes('/'))
            .map(row => row.path), digest: keepDigest },
        identity, delete: deletions, stash, state: state ? 'present' : 'absent',
        reclaimableBytes: measure ? Number(bytes) : null };
    value.digest = planDigest({ version: 1, workspace, scope, mode, keep: keepListing, identity,
        delete: targets.map(target => ({ relative: target.relative, type: typeOf(target.stat), dev: String(target.stat.dev),
            ino: String(target.stat.ino) })), stash, state: value.state });
    Object.defineProperty(value, 'targets', { value: targets, enumerable: false });
    return Object.defineProperty(value, 'keepListing', { value: keepListing, enumerable: false });
}

/** Removes one proven target: same device and inode as planned, no mount at or under it. */
function removeTarget(ctx, file, expected) {
    const stat = ctx.lstat(file);
    requireProof(stat.dev === expected.dev && stat.ino === expected.ino && typeOf(stat) === typeOf(expected),
        'QA_TEARDOWN_TARGET_CHANGED');
    if (realDirectory(stat)) walkSameDevice(ctx, file, expected.dev);
    ctx.assertNoMount(file);
    fs.rmSync(file, { recursive: realDirectory(stat), force: false });
    requireProof(ctx.present(file) === null, 'QA_TEARDOWN_REMOVAL_UNVERIFIED');
}

/**
 * Keep-data reduction. Recomputes the plan and requires the given digest,
 * deletes the planned targets, then requires the keep listing and the
 * identity fingerprint to be identical to the plan. Idempotent: an already
 * reduced workspace plans `delete: []`.
 */
export function reduceWorkspace({ paths, owner, scope, planDigest: expected, hooks = {} }) {
    requireProof(DIGEST.test(expected || ''), 'QA_TEARDOWN_USAGE_INVALID');
    const ctx = context({ paths, owner, hooks });
    const plan = planWorkspace({ paths, owner, scope, mode: 'keep-data', hooks });
    requireProof(plan.digest === expected, 'QA_TEARDOWN_PLAN_CHANGED');
    const { workspace } = ctx.paths;
    if (plan.workspace === 'absent') {
        return { result: 'reduced', scope, workspace: 'absent', deleted: [], keep: plan.keep, identity: [], digest: plan.digest };
    }
    // The live policy is deleted only once it is parked in the state directory (contract 2 r2).
    if (plan.delete.some(item => item.relative === '.ploinky/data/router-security') && livePolicy(ctx)?.initialized) {
        const stash = ctx.present(path.join(ctx.paths.state, STASH_NAME, 'policy-state.json'));
        requireProof(stateDirectory(ctx)?.stash && stash && stash.isFile() && !stash.isSymbolicLink(), 'QA_TEARDOWN_STASH_REQUIRED');
    }
    const deleted = [];
    try {
        for (const target of plan.targets) {
            // The identity recorded by the plan whose digest was just matched.
            removeTarget(ctx, path.join(workspace, target.relative), target.stat);
            deleted.push(target.relative);
            if (hooks.afterRemove) hooks.afterRemove(target.relative);
        }
    } catch (error) {
        throw Object.assign(error, { detail: { ...(error.detail || {}), deleted: [...deleted] } });
    }
    const after = planWorkspace({ paths, owner, scope, mode: 'keep-data', hooks });
    requireProof(after.delete.length === 0 && after.keep.digest === plan.keep.digest
        && JSON.stringify(after.identity) === JSON.stringify(plan.identity), 'QA_TEARDOWN_KEEP_CHANGED', { detail: { deleted } });
    return { result: 'reduced', scope, workspace: 'present', deleted, keep: after.keep, identity: after.identity,
        digest: plan.digest };
}

/** Copies one policy entry with `cp -a` and proves the copy with `diff -qr` and an owner and mode comparison. */
function copyVerified(ctx, from, to) {
    const copy = spawnSync('cp', ['-a', '--', from, to], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 600_000 });
    requireProof(!copy.error && copy.status === 0, 'QA_TEARDOWN_POLICY_COPY_FAILED');
    const diff = spawnSync('diff', ['-qr', '--', from, to], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 600_000 });
    requireProof(!diff.error && diff.status === 0, 'QA_TEARDOWN_POLICY_COPY_FAILED');
    const compare = (left, right) => {
        const a = ctx.lstat(left), b = ctx.lstat(right);
        requireProof(typeOf(a) === typeOf(b) && a.mode === b.mode && a.uid === b.uid && a.gid === b.gid
            && !a.isSymbolicLink() && (a.isFile() || a.isDirectory()), 'QA_TEARDOWN_POLICY_COPY_FAILED');
        if (a.isDirectory()) {
            const names = fs.readdirSync(left).sort();
            requireProof(JSON.stringify(names) === JSON.stringify(fs.readdirSync(right).sort()), 'QA_TEARDOWN_POLICY_COPY_FAILED');
            for (const name of names) compare(path.join(left, name), path.join(right, name));
        }
    };
    compare(from, to);
}

/** Discards `router-security.tmp-*` and `.removing-*` leftovers of an interrupted stash operation. */
function discardLeftovers(ctx, stateStat) {
    const discarded = [];
    for (const name of fs.readdirSync(ctx.paths.state).sort()) {
        if (!LEFTOVER.test(name)) continue;
        const file = path.join(ctx.paths.state, name);
        const stat = ctx.lstat(file);
        requireProof(realDirectory(stat) && stat.dev === stateStat.dev, 'QA_TEARDOWN_STATE_INVALID');
        removeTarget(ctx, file, stat);
        discarded.push(name);
    }
    return discarded;
}

function removeStash(ctx, stateStat) {
    const stash = path.join(ctx.paths.state, STASH_NAME);
    const stat = ctx.present(stash);
    if (!stat) return false;
    requireProof(realDirectory(stat) && stat.dev === stateStat.dev, 'QA_TEARDOWN_STATE_INVALID');
    const removing = path.join(ctx.paths.state, `${STASH_NAME}.removing-${process.pid}`);
    requireProof(ctx.present(removing) === null, 'QA_TEARDOWN_STATE_INVALID');
    fs.renameSync(stash, removing);
    if (ctx.hooks.afterRename) ctx.hooks.afterRename(removing);
    removeTarget(ctx, removing, ctx.lstat(removing));
    return true;
}

/**
 * Parks the live router access policy in the state directory (contract 2 r2):
 * a temporary directory, `cp -a`, `diff -qr`, then a rename. An existing stash
 * is never overwritten, and an earlier temporary copy is discarded first.
 */
export function stashPolicy({ paths, owner, hooks = {} }) {
    const ctx = context({ paths, owner, hooks });
    const state = stateDirectory(ctx);
    requireProof(state, 'QA_TEARDOWN_STATE_MISSING');
    const discarded = discardLeftovers(ctx, state.stat);
    if (state.stash) return { result: 'stash-kept', copied: [], discarded };
    const policy = livePolicy(ctx);
    if (!policy?.initialized) return { result: 'no-policy', copied: [], discarded };
    const entries = POLICY_ENTRIES.filter(name => {
        const stat = ctx.present(path.join(policy.directory, name));
        if (!stat) return false;
        requireProof(name === 'policy-audit-archive' ? realDirectory(stat) : stat.isFile() && !stat.isSymbolicLink(),
            'QA_TEARDOWN_UNSAFE_PATH');
        return true;
    });
    const temporary = path.join(ctx.paths.state, `${STASH_NAME}.tmp-${process.pid}`);
    fs.mkdirSync(temporary, { mode: 0o700 });
    for (const name of entries) {
        copyVerified(ctx, path.join(policy.directory, name), path.join(temporary, name));
        if (hooks.afterCopy) hooks.afterCopy(name);
    }
    fs.renameSync(temporary, path.join(ctx.paths.state, STASH_NAME));
    return { result: 'stashed', copied: entries, discarded };
}

/**
 * Restores the stash into the freshly initialized live policy, proves each copy,
 * then removes the stash at once (`.removing-<pid>`, then deleted), so the live
 * policy is the only authority from here on. With no stash nothing is copied.
 */
export function stashRestore({ paths, owner, hooks = {} }) {
    const ctx = context({ paths, owner, hooks });
    const state = stateDirectory(ctx);
    if (!state) return { result: 'no-stash', copied: [], discarded: [], stashRemoved: false };
    const discarded = discardLeftovers(ctx, state.stat);
    if (!state.stash) return { result: 'no-stash', copied: [], discarded, stashRemoved: false };
    const policy = livePolicy(ctx);
    requireProof(policy?.initialized, 'QA_TEARDOWN_POLICY_NOT_INITIALIZED');
    const stash = path.join(ctx.paths.state, STASH_NAME);
    const liveStat = ctx.lstat(policy.directory);
    const copied = [];
    for (const name of POLICY_ENTRIES) {
        const from = path.join(stash, name);
        const fromStat = ctx.present(from);
        if (!fromStat) continue;
        requireProof(!fromStat.isSymbolicLink(), 'QA_TEARDOWN_STATE_INVALID');
        const to = path.join(policy.directory, name);
        const existing = ctx.present(to);
        if (existing) {
            requireProof(existing.dev === liveStat.dev, 'QA_TEARDOWN_MOUNT_INSIDE');
            removeTarget(ctx, to, existing);
        }
        copyVerified(ctx, from, to);
        copied.push(name);
        if (hooks.afterCopy) hooks.afterCopy(name);
    }
    const stashRemoved = removeStash(ctx, state.stat);
    return { result: 'restored', copied, discarded, stashRemoved };
}

/** Removes the stash and any leftover temporary copy. */
export function stashClear({ paths, owner, hooks = {} }) {
    const ctx = context({ paths, owner, hooks });
    const state = stateDirectory(ctx);
    if (!state) return { result: 'cleared', removed: false, discarded: [] };
    const discarded = discardLeftovers(ctx, state.stat);
    return { result: 'cleared', removed: removeStash(ctx, state.stat), discarded };
}

/** Removes the leftover delete-data tombstones (contract 4 r2 fix round, item 4). */
export function finishDeletions({ paths, owner, hooks = {} }) {
    const ctx = context({ paths, owner, hooks });
    const finished = [];
    for (const item of pendingDeletions(ctx)) {
        removeTarget(ctx, item.file, item.stat);
        finished.push(item.name);
    }
    return { result: 'finished', finished };
}

/**
 * Delete-data mode. Leftover tombstones are finished first. Then the workspace
 * and the state directory are each renamed to a tombstone beside them, and only
 * then removed, so a crash leaves them absent rather than half-deleted.
 */
export function deleteData({ paths, owner, hooks = {} }) {
    const ctx = context({ paths, owner, hooks });
    const { finished } = finishDeletions({ paths, owner, hooks });
    const plan = planWorkspace({ paths, owner, scope: 'destroy', mode: 'delete-data', hooks });
    const result = { result: 'deleted', workspace: 'absent', state: 'absent', finishedDeletions: finished };
    const renamed = [];
    for (const [key, file] of [['workspace', ctx.paths.workspace], ['state', ctx.paths.state]]) {
        const stat = ctx.present(file);
        if (!stat) continue;
        requireProof(realDirectory(stat) && stat.uid === ctx.owner && fs.realpathSync(file) === file,
            key === 'state' ? 'QA_TEARDOWN_STATE_INVALID' : 'QA_TEARDOWN_UNSAFE_PATH');
        requireProof(stat.dev === ctx.lstat(path.dirname(file)).dev, 'QA_TEARDOWN_MOUNT_INSIDE');
        ctx.assertNoMount(file);
        const tombstone = path.join(path.dirname(file), `${deletingPrefix(file)}${process.pid}`);
        requireProof(ctx.present(tombstone) === null, 'QA_TEARDOWN_TOMBSTONE_EXISTS');
        fs.renameSync(file, tombstone);
        if (hooks.afterRename) hooks.afterRename(tombstone);
        renamed.push({ key, tombstone, stat });
    }
    for (const item of renamed) {
        // A rename keeps the inode, so the identity recorded before it still applies.
        removeTarget(ctx, item.tombstone, item.stat);
        result[item.key] = 'removed';
        if (hooks.afterRemove) hooks.afterRemove(item.key);
    }
    return { ...result, digest: plan.digest };
}

/**
 * Classifies and prunes the legacy backups under `paths.backups`. Ported from
 * the retired privileged backup helper's `prunePrivileged` at 916078b2 (I1): only `complete-redeploy`
 * and `no-workspace` backups go, each through a `.pruning-` tombstone, with
 * the siblings of a removed backup; everything else is kept and reported. The
 * live workspace may be absent (delete-data removes it first). A mount at or
 * under the backups root refuses (contract 1 r2).
 */
export function removeLegacyBackups({ paths, owner, hooks = {} }) {
    const ctx = context({ paths, owner, hooks });
    const removedNames = [];
    try { return pruneAll(ctx, removedNames, false); }
    catch (error) { throw Object.assign(error, { detail: { ...(error.detail || {}), removed: [...removedNames] } }); }
}

/**
 * Read-only preview of `removeLegacyBackups`: the same root, mount, tombstone,
 * classification and device proofs, with nothing renamed or removed, so a
 * destroy plan refuses before anything is stopped.
 */
export function planLegacyBackups({ paths, owner, hooks = {} }) {
    return pruneAll(context({ paths, owner, hooks }), [], true);
}

function pruneAll(ctx, removedNames, dryRun) {
    const { backups: root, workspace } = ctx.paths;
    const uid = ctx.owner;
    const { lstat, present } = ctx;
    const result = { result: 'pruned', removed: [], retained: [], retainedSiblings: [], unrecognized: [], replayedTombstones: [] };
    const rootStat = present(root);
    if (!rootStat) {
        return dryRun ? { result: 'planned', remove: [], replayTombstones: [], retained: [], retainedSiblings: [], unrecognized: [] } : result;
    }
    requireProof(realDirectory(rootStat) && rootStat.uid === uid && fs.realpathSync(root) === root, 'QA_TEARDOWN_BACKUPS_INVALID');
    const workspaceStat = present(workspace);
    requireProof(!workspaceStat || realDirectory(workspaceStat), 'QA_TEARDOWN_UNSAFE_PATH');
    const isLive = stat => Boolean(workspaceStat && stat.dev === workspaceStat.dev && stat.ino === workspaceStat.ino);
    const rootDev = rootStat.dev;
    ctx.assertNoMount(root);

    const entryIdentity = (file, directory) => {
        const stat = present(file);
        if (!stat || stat.isSymbolicLink() || stat.uid !== uid || stat.dev !== rootDev || isLive(stat)) return null;
        if (directory ? !stat.isDirectory() || fs.realpathSync(file) !== file : !stat.isFile()) return null;
        return stat;
    };
    const walk = top => walkSameDevice(ctx, top, rootDev);
    const readReceipt = file => {
        if (ctx.hooks.beforeRead) ctx.hooks.beforeRead(file);
        const stat = lstat(file);
        if (!stat.isFile() || stat.isSymbolicLink() || stat.size > BigInt(RECEIPT_LIMIT)) return null;
        try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; }
    };
    const isRollbackMarker = name => BACKUP_INNER_ENTRIES.rollbackMarkers.some(marker => typeof marker === 'string'
        ? marker === name : marker.test(name));

    const backups = [], tombstones = [], siblings = new Map(), unrecognized = [];
    for (const name of fs.readdirSync(root).sort()) {
        const file = path.join(root, name);
        if (BACKUP.test(name)) {
            const stat = present(file);
            if (stat && realDirectory(stat) && stat.uid === uid && (stat.mode & 0o077n) === 0n
                && fs.realpathSync(file) === file && stat.dev === rootDev && !isLive(stat)) backups.push({ name, file, stat });
            else unrecognized.push(name);
        } else if (TOMBSTONE.test(name)) {
            const stat = entryIdentity(file, true);
            requireProof(stat, 'QA_TEARDOWN_TOMBSTONE_INVALID');
            tombstones.push({ name, backup: TOMBSTONE.exec(name)[1], file, stat });
        } else if (SIBLING.test(name)) {
            const [, base, suffix] = SIBLING.exec(name);
            if (!siblings.has(base)) siblings.set(base, []);
            siblings.get(base).push({ name, suffix, file });
        } else unrecognized.push(name);
    }
    const backupNames = new Set(backups.map(item => item.name));
    const removableSiblings = base => (siblings.get(base) || []).map(item => ({ ...item,
        stat: entryIdentity(item.file, item.suffix === 'helpers') }));

    const classify = backup => {
        const entries = fs.readdirSync(backup.file);
        if (entries.some(isRollbackMarker)) return 'rollback-attempted';
        for (const entry of entries) {
            if (!BACKUP_INNER_ENTRIES.completion.includes(entry)) return 'unrecognized-entry';
            const stat = lstat(path.join(backup.file, entry));
            const valid = DIRECTORY_ENTRIES.has(entry) ? realDirectory(stat) : stat.isFile() && !stat.isSymbolicLink();
            if (!valid) return 'unrecognized-entry';
        }
        const own = removableSiblings(backup.name);
        if (own.some(item => !item.stat)) return 'unrecognized-entry';
        const has = entry => entries.includes(entry);
        const quiesced = has('quiesce.log') || own.some(item => item.suffix === 'quiesce.log');
        if (!has('workspace')) {
            if (quiesced) return 'stop-attempted-unpreserved';
            // A preservation receipt that names a workspace which is gone is not a clean abort.
            if (has('preservation.json')) {
                const preservation = readReceipt(path.join(backup.file, 'preservation.json'));
                if (!preservation || preservation.source !== null) return 'incomplete-redeploy';
            }
            return 'no-workspace';
        }
        const preservation = has('preservation.json') ? readReceipt(path.join(backup.file, 'preservation.json')) : null;
        const policy = has('policy-restoration.json') ? readReceipt(path.join(backup.file, 'policy-restoration.json')) : null;
        const selections = has('restored-selections.json') ? readReceipt(path.join(backup.file, 'restored-selections.json')) : null;
        const complete = preservation?.exactCopiesVerified === true
            && preservation.source === path.join(backup.file, 'workspace') && preservation.target === workspace
            && policy?.exactCopiesVerified === true
            && selections !== null && typeof selections === 'object' && FULL_ID.test(String(selections.boxId || ''));
        return complete ? 'complete-redeploy' : 'incomplete-redeploy';
    };

    // Phase 1: classify and prove every identity, including the full walks, before the first rename or removal.
    const prunable = [];
    for (const backup of backups) {
        const backupClass = classify(backup);
        if (!PRUNABLE_CLASSES.includes(backupClass)) { result.retained.push({ name: backup.name, class: backupClass }); continue; }
        prunable.push({ ...backup, siblings: removableSiblings(backup.name) });
    }
    const replay = tombstones.map(item => ({ ...item,
        siblings: backupNames.has(item.backup) ? [] : removableSiblings(item.backup).filter(sibling => sibling.stat) }));
    for (const item of [...replay, ...prunable]) {
        walk(item.file);
        for (const sibling of item.siblings) if (sibling.stat.isDirectory()) walk(sibling.file);
    }
    const kept = new Set([...replay, ...prunable].flatMap(item => item.siblings.map(sibling => sibling.name)));
    for (const [base, items] of siblings) {
        if (backupNames.has(base) && !prunable.some(item => item.name === base)) {
            // The siblings of a kept backup stay, reported with it.
            for (const item of items) result.retainedSiblings.push(item.name);
            continue;
        }
        for (const item of items) if (!kept.has(item.name)) unrecognized.push(item.name);
    }
    result.unrecognized = [...new Set(unrecognized)].sort();
    result.retainedSiblings.sort();
    if (dryRun) {
        return { result: 'planned', remove: prunable.map(item => item.name), replayTombstones: replay.map(item => item.name),
            retained: result.retained, retainedSiblings: result.retainedSiblings, unrecognized: result.unrecognized };
    }

    const removeSiblings = item => {
        for (const sibling of item.siblings) {
            const stat = lstat(sibling.file);
            requireProof(!stat.isSymbolicLink() && stat.uid === uid && stat.dev === rootDev && stat.ino === sibling.stat.ino,
                'QA_TEARDOWN_SIBLING_CHANGED');
            removeTarget(ctx, sibling.file, stat);
        }
    };
    const removeTombstone = (file, expected) => {
        const stat = lstat(file);
        requireProof(realDirectory(stat) && stat.uid === uid && stat.dev === rootDev && stat.ino === expected.ino
            && stat.dev === expected.dev && !isLive(stat), 'QA_TEARDOWN_TOMBSTONE_CHANGED');
        removeTarget(ctx, file, stat);
    };

    // Phase 2: leftover tombstones first, then each prunable backup. Siblings go
    // before the tombstone, so an interruption always leaves a tombstone to replay.
    for (const item of replay) {
        removeSiblings(item);
        removeTombstone(item.file, item.stat);
        result.replayedTombstones.push(item.name);
    }
    for (const item of prunable) {
        const tombstone = path.join(root, `.pruning-${item.name}`);
        requireProof(present(tombstone) === null, 'QA_TEARDOWN_TOMBSTONE_EXISTS');
        const before = lstat(item.file);
        requireProof(before.ino === item.stat.ino && before.dev === item.stat.dev && !before.isSymbolicLink(),
            'QA_TEARDOWN_BACKUP_CHANGED');
        fs.renameSync(item.file, tombstone);
        if (ctx.hooks.afterRename) ctx.hooks.afterRename(tombstone);
        removeSiblings(item);
        removeTombstone(tombstone, item.stat);
        removedNames.push(item.name);
        result.removed.push(item.name);
    }
    return result;
}

const OPERATIONS = Object.freeze({
    'plan-workspace': { required: ['--scope', '--mode', '--owner'], optional: ['--measure'], run: planWorkspace },
    'reduce-workspace': { required: ['--scope', '--plan-digest', '--owner'], optional: [], run: reduceWorkspace },
    'stash-policy': { required: ['--owner'], optional: [], run: stashPolicy },
    'stash-restore': { required: ['--owner'], optional: [], run: stashRestore },
    'stash-clear': { required: ['--owner'], optional: [], run: stashClear },
    'delete-data': { required: ['--owner'], optional: [], run: deleteData },
    'finish-deletions': { required: ['--owner'], optional: [], run: finishDeletions },
    'plan-legacy-backups': { required: ['--owner'], optional: [], run: planLegacyBackups },
    'remove-legacy-backups': { required: ['--owner'], optional: [], run: removeLegacyBackups },
});
const VALUE_FLAGS = Object.freeze({
    '--scope': value => SCOPES.includes(value),
    '--mode': value => MODES.includes(value),
    '--owner': value => /^[1-9][0-9]{0,9}$/.test(value),
    '--plan-digest': value => DIGEST.test(value),
});

/** Parses `<operation> --flag value …`; every required flag exactly once, no other flag. */
export function parsePrivilegedArguments(argv) {
    const [operation, ...rest] = argv;
    const spec = OPERATIONS[operation];
    requireProof(spec, 'QA_TEARDOWN_USAGE_INVALID');
    const options = {};
    for (let index = 0; index < rest.length; index += 1) {
        const flag = rest[index];
        requireProof([...spec.required, ...spec.optional].includes(flag) && !(flag in options), 'QA_TEARDOWN_USAGE_INVALID');
        if (flag === '--measure') { options[flag] = true; continue; }
        const value = rest[index + 1];
        requireProof(typeof value === 'string' && VALUE_FLAGS[flag](value), 'QA_TEARDOWN_USAGE_INVALID');
        options[flag] = value;
        index += 1;
    }
    requireProof(spec.required.every(flag => flag in options), 'QA_TEARDOWN_USAGE_INVALID');
    return { operation, options: { scope: options['--scope'], mode: options['--mode'], owner: Number(options['--owner']),
        planDigest: options['--plan-digest'], measure: options['--measure'] === true } };
}

/** One operation against explicit paths; the CLI pins them, tests pass fixtures. */
export function privilegedOperation(operation, { paths, owner, scope, mode, planDigest: digest, measure, hooks = {} }) {
    const spec = OPERATIONS[operation];
    requireProof(spec, 'QA_TEARDOWN_USAGE_INVALID');
    const value = spec.run({ paths, owner, scope, mode, planDigest: digest, measure, hooks });
    return JSON.parse(JSON.stringify(value));
}

const safeCode = (error, fallback) => /^QA_[A-Z_]+$/.test(error?.code || '') ? error.code : fallback;

/**
 * Runs one argv against `paths` and returns the exit status and the single
 * JSON line. Only `runPrivilegedCli` is a production entry, and it pins the
 * QA paths; tests pass fixture paths and a uid stub here.
 */
export function runPrivilegedArgv(argv, { paths, getuid = process.getuid, hooks = {} }) {
    try {
        const { operation, options } = parsePrivilegedArguments(argv);
        requireProof(typeof getuid === 'function' && getuid() === 0, 'QA_TEARDOWN_ROOT_REQUIRED');
        const result = privilegedOperation(operation, { ...options, paths, hooks });
        return { status: 0, stdout: JSON.stringify(result) + '\n' };
    } catch (error) {
        const detail = error?.detail && typeof error.detail === 'object' ? error.detail : {};
        const safe = Object.fromEntries(Object.entries(detail).filter(([, item]) => Array.isArray(item)
            && item.every(entry => typeof entry === 'string' && entry.length <= 4096)));
        return { status: 1, stdout: JSON.stringify({ result: 'failed', code: safeCode(error, 'QA_TEARDOWN_PRIVILEGED_FAILED'),
            ...safe }) + '\n' };
    }
}

/** CLI form on the pinned QA paths; exactly one JSON line on stdout, exit 0 on success and 1 on any failure. */
export function runPrivilegedCli(argv) {
    const { status, stdout } = runPrivilegedArgv(argv, { paths: QA_TEARDOWN_PATHS });
    process.stdout.write(stdout);
    return status;
}

// Loaded from stdin, argv[1] is '-' and this module has no file of its own.
const fromStdin = process.argv[1] === '-' && !import.meta.url.endsWith('/qa-teardown-privileged.mjs');
const asFile = !fromStdin && Boolean(process.argv[1]) && import.meta.url.startsWith('file:')
    && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (fromStdin || asFile) process.exitCode = runPrivilegedCli(process.argv.slice(2));
